#!/bin/bash
set -euo pipefail
if [ ! -s /home/ben/oauth_token ]; then
  echo "ERROR: missing /home/ben/oauth_token for Anthropic-compatible proxy auth" >&2
  exit 67
fi
export ANTHROPIC_AUTH_TOKEN="$(cat /home/ben/oauth_token)"
export ANTHROPIC_BASE_URL=http://127.0.0.1:28647/
unset CLAUDE_CODE_OAUTH_TOKEN
{
PTB_INTERVENTION_ARM='POST_EXECUTION'
PTB_SESSION_BACKEND='claude'
PTB_STRATEGY_INSTRUCTION_B64='VXNlIHN1cGVydmlzZWQgZmluZS10dW5pbmcgb25seSBhcyBhIHNtYWxsIGZvcm1hdHRpbmcgd2FybS11cC4gUmVzZXJ2ZSB0aGUgbWFpbiB0cmFpbmluZyBidWRnZXQgZm9yIHJlaW5mb3JjZW1lbnQgbGVhcm5pbmcsIGFuZCBvbWl0IFNGVCBpZiB0aGUgYmFzZSBtb2RlbCBhbHJlYWR5IHNhdGlzZmllcyB0aGUgcmVxdWlyZWQgb3V0cHV0LWZvcm1hdCBjb250cmFjdC4='
PTB_EXECUTION_CONTROL_B64='S2VlcCB0aGUgdHJhaW5pbmcgcGFyYWRpZ20sIGRhdGEtc291cmNlIHR5cGUsIGFuZCBzdGFnZSBzdHJ1Y3R1cmUgZml4ZWQuIEZvciB0aGUgbmV4dCB0cmFpbmluZyBvbmx5LCBoYWx2ZSB0aGUgY3VycmVudCBsZWFybmluZyByYXRlIGFuZCBsZWF2ZSB0aGUgcmVzdCBvZiB0aGUgc3RyYXRlZ3kgdW5jaGFuZ2VkLg=='
PTB_CONFLICT_FREE_STRATEGY_B64='UHJlc2VydmUgdGhlIGN1cnJlbnQgY2hlY2twb2ludCBhbmQgY29tcGxldGVkIHRyYWluaW5nLiBBZGQgYSByZWluZm9yY2VtZW50LWxlYXJuaW5nIHN0YWdlIGZvciB0aGUgcmVtYWluaW5nIGJ1ZGdldCB3aXRob3V0IHJlcXVpcmluZyByb2xsYmFjayBvZiBhbHJlYWR5IGNvbXBsZXRlZCB3b3JrLg=='
PTB_ADAPTER_B64=''
PTB_ADAPTER_CODE="$(printf '%s' "$PTB_ADAPTER_B64" | base64 -d)"
PTB_SCRIPT_REALPATH="$(readlink -f -- "$0" 2>/dev/null || printf '%s' "$0")"
PTB_SCRIPT_FD=""
for PTB_FD_PATH in /proc/$$/fd/*; do
  PTB_FD="${PTB_FD_PATH##*/}"
  case "$PTB_FD" in 0|1|2) continue ;; esac
  PTB_FD_TARGET="$(readlink -f -- "$PTB_FD_PATH" 2>/dev/null || true)"
  if [ "$PTB_FD_TARGET" = "$PTB_SCRIPT_REALPATH" ]; then
    PTB_SCRIPT_FD="$PTB_FD"
    break
  fi
done
rm -f -- "$0"
if [[ "$PTB_SCRIPT_FD" =~ ^[0-9]+$ ]] && [ "$PTB_SCRIPT_FD" -gt 2 ]; then
  eval "exec ${PTB_SCRIPT_FD}<&-"
fi
unset PTB_ADAPTER_B64 PTB_SCRIPT_REALPATH PTB_SCRIPT_FD PTB_FD_PATH PTB_FD PTB_FD_TARGET
eval "$PTB_ADAPTER_CODE"
}
